// src/commands/config/getSetReset.ts
var ConfigActions = class extends BaseAction {
  constructor() {
    super();
  }
  set(keyValue) {
    const [key, value] = keyValue.split("=");
    this.startSpinner(`Updating configuration: ${key}`);
    if (!key || value === void 0) {
      this.failSpinner("Invalid format. Use 'key=value'.");
      return;
    }
    this.writeConfig(key, value);
    this.succeedSpinner(`Configuration successfully updated`);
  }
  get(key) {
    this.startSpinner(key ? `Retrieving value for: ${key}` : "Retrieving all configurations");
    if (key) {
      const value = this.getConfigByKey(key);
      if (value === null) {
        this.failSpinner(`No configuration found for '${key}'.`);
      } else {
        this.succeedSpinner(`Configuration successfully retrieved`, `${key}=${value}`);
      }
    } else {
      const config = this.getConfig();
      this.succeedSpinner("All configurations successfully retrieved", JSON.stringify(config, null, 2));
    }
  }
  reset(key) {
    this.startSpinner(`Resetting configuration: ${key}`);
    const config = this.getConfig();
    if (!(key in config)) {
      this.failSpinner(`Configuration key '${key}' does not exist.`);
      return;
    }
    delete config[key];
    this.writeConfig(key, void 0);
    this.succeedSpinner(`Configuration successfully reset`);
  }
};

// src/commands/config/index.ts
function initializeConfigCommands(program2) {
  const configActions = new ConfigActions();
  const configCommand = program2.command("config").description("Manage CLI configuration, including the default network");
  configCommand.command("set").description("Set a configuration value").argument("<key=value>", "Configuration key-value pair to set").action((keyValue) => configActions.set(keyValue));
  configCommand.command("get").description("Get the current configuration").argument("[key]", "Configuration key to retrieve").action((key) => configActions.get(key));
  configCommand.command("reset").description("Reset a configuration value to its default").argument("<key>", "Configuration key to reset").action((key) => configActions.reset(key));
  return program2;
}

